{$ param image_url label="Thumbnail URL" default="https://picsum.photos/400/300" description="Resource thumbnail image." type="fileurl" $}
{$ param image_alt label="Thumbnail Alt" default="" description="Accessibility description." $}
{$ param title label="Title" default="Resource Title" description="Card heading." $}
{$ param format_meta label="Format Meta" default="PDF" description="E.g. 'PDF · 2 pages' or 'Canva template'." $}
{$ param download_href label="Download URL" default="#" description="Where the button links." $}
{$ param download_label label="Download Label" default="Download" description="Button text." $}

<div class="ss-pc mb-4">
  <div class="ss-pc-img">
    <img src="{$= image_url $}" alt="{$= image_alt $}" />
  </div>
  <div class="ss-pc-content">
    <h3>{$= title $}</h3>
    <span class="ss-xxs uppercase text-neutral-dark">{$= format_meta $}</span>
    {$ slot description $}
      <p>Short description of the resource.</p>
    {$ /slot $}
    <a href="{$= download_href $}" class="btn btn-primary">{$= download_label $}</a>
  </div>
</div>
